DERIVED = {'CARGO_TARGET_DIR': '/cargo-target', 'HOME': '/home', 'P1_U04_ARTIFACTS_ROOT': '/artifacts', 'P1_U04_DIST_ROOT': '/dist', 'P1_U04_SOURCE_ROOT': '/source', 'P1_U04_STAGING_ROOT': '', 'P1_U04_VENV_ROOT': '/venv', 'PWD': '/source', 'PYO3_PYTHON': '/venv/bin/python', 'TEMP': '/tmp', 'TMP': '/tmp', 'TMPDIR': '/tmp', 'VIRTUAL_ENV': '/venv'}
DYNAMIC = ('P1_U04_SOURCE_ST_DEV', 'P1_U04_SOURCE_ST_INO')
OVERRIDES = {'CC': 'clang', 'CXX': 'clang++', 'LDSHARED': 'clang -shared'}
RUSTFLAGS_APPEND = ' -C link-arg=-s'

stage = os.environ.get('P1_U04_STAGING_ROOT', '')
prefix = BUILD_ROOT + '/stage-'
token = stage[len(prefix):] if stage.startswith(prefix) else ''
if len(token) != 16 or any(c not in '0123456789abcdef' for c in token):
    raise SystemExit('cargo wrapper environment is not exact')
expected = dict(STATIC)
expected.update({name: stage + suffix for name, suffix in DERIVED.items()})
dynamic = {}
for name in DYNAMIC:
    value = os.environ.get(name, '')
    if not value or value[0] == '0' or not value.isascii() or not value.isdecimal():
        raise SystemExit('cargo wrapper source identity is not exact')
    dynamic[name] = value
expected.update(dynamic)
expected.update(OVERRIDES)
expected['RUSTFLAGS'] += RUSTFLAGS_APPEND
if dict(os.environ) != expected:
    raise SystemExit('cargo wrapper environment is not exact')
if len(sys.argv) < 2 or sys.argv[1] != 'build':
    raise SystemExit('cargo wrapper only permits build')
if os.getcwd() != expected['PWD']:
    raise SystemExit('cargo wrapper working directory is not exact')
source = os.stat('.')
if (str(source.st_dev), str(source.st_ino)) != (
    dynamic['P1_U04_SOURCE_ST_DEV'], dynamic['P1_U04_SOURCE_ST_INO']
):
    raise SystemExit('cargo wrapper source identity is not exact')
os.execve(CARGO, [CARGO, 'build', '--locked', '--offline', *sys.argv[2:]], expected)
